import{_ as a,o as t,c as r,a5 as i}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"BrandHub — Technical Document (v1.0, V2 business model)","description":"","frontmatter":{},"headers":[],"relativePath":"BrandHub_Technical_Document.md","filePath":"BrandHub_Technical_Document.md"}'),c={name:"BrandHub_Technical_Document.md"};function o(s,e,n,h,d,l){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="brandhub-—-technical-document-v1-0-v2-business-model" tabindex="-1">BrandHub — Technical Document (v1.0, V2 business model) <a class="header-anchor" href="#brandhub-—-technical-document-v1-0-v2-business-model" aria-label="Permalink to &quot;BrandHub — Technical Document (v1.0, V2 business model)&quot;">​</a></h1><p>&gt; DA-1159 (DA-E05-08). Tổng hợp toàn bộ artifact E05, dùng làm tài liệu tham khảo chính cho developer + nộp mentor. &gt; Cập nhật 2026-09-17 theo model V2: <code>Agency → Workspace → Media Package → Media Campaign → Task</code>.</p><h2 id="_1-system-overview" tabindex="-1">1. System Overview <a class="header-anchor" href="#_1-system-overview" aria-label="Permalink to &quot;1. System Overview&quot;">​</a></h2><ul><li><strong>Product:</strong> BrandHub — B2B SaaS, AI-powered multi-channel content production cho marketing agency.</li><li><strong>6 role:</strong> ADMIN, OWNER (Agency), MANAGER/CREATOR/CLIENT (theo Workspace, gán độc lập từng Workspace), GUEST.</li><li>Xem chi tiết: <a href="./ba/00-overview.html">docs/ba/00-overview.md</a>, <a href="./ba/01-organization-structure.html">docs/ba/01-organization-structure.md</a>.</li><li>Diagram tổng quan: <a href="./architecture/architecture.html">docs/architecture/architecture.html</a>.</li></ul><h2 id="_2-service-boundaries" tabindex="-1">2. Service Boundaries <a class="header-anchor" href="#_2-service-boundaries" aria-label="Permalink to &quot;2. Service Boundaries&quot;">​</a></h2><p>7 thành phần: <code>api-gateway</code>, <code>business-service</code>, <code>ai-service</code>, <code>publisher-service</code>, <code>web-dashboard</code>, <code>mobile-app</code>, <code>infrastructure</code>.</p><p>Chi tiết ownership/trách nhiệm từng service: <a href="./service-boundaries.html">docs/service-boundaries.md</a>.</p><h2 id="_3-database-design" tabindex="-1">3. Database Design <a class="header-anchor" href="#_3-database-design" aria-label="Permalink to &quot;3. Database Design&quot;">​</a></h2><ul><li><strong>PostgreSQL:</strong> 23 bảng (Identity, Organization, Commerce, Collaborator, Billing) — business-service sở hữu duy nhất.</li><li><strong>MongoDB:</strong> 17 collection tổng cộng, chia 3 service (business 14, ai 2, publisher 1).</li><li><strong>Redis:</strong> JWT blacklist, rate limit, session cache — business-service sở hữu.</li><li><strong>ChromaDB + S3:</strong> ai-service sở hữu.</li></ul><p>Chi tiết: <a href="./architecture/db-ownership-diagram.html">docs/architecture/db-ownership-diagram.html</a>, schema đầy đủ: <a href="./database/schema-v2/brandhub-dbml.dbml.html">docs/database/schema-v2/brandhub-dbml.dbml</a>.</p><h2 id="_4-api-contracts" tabindex="-1">4. API Contracts <a class="header-anchor" href="#_4-api-contracts" aria-label="Permalink to &quot;4. API Contracts&quot;">​</a></h2><ul><li><strong>business-service ↔ ai-service (REST, đồng bộ):</strong> <a href="./architecture/business-ai-rest-contract.html">docs/architecture/business-ai-rest-contract.md</a>.</li><li><strong>business-service ↔ publisher-service (RabbitMQ, bất đồng bộ):</strong> <a href="./architecture/rabbitmq-publisher-contract.html">docs/architecture/rabbitmq-publisher-contract.html</a>.</li><li><strong>RBAC 2 tầng (Agency-level + Workspace-level):</strong> <a href="./ba/10-roles-permissions-matrix.html">docs/ba/10-roles-permissions-matrix.md</a>.</li></ul><h2 id="_5-sequence-diagrams" tabindex="-1">5. Sequence Diagrams <a class="header-anchor" href="#_5-sequence-diagrams" aria-label="Permalink to &quot;5. Sequence Diagrams&quot;">​</a></h2><p>4 luồng lõi (Content Creation, Approval Workflow, Auto-Publishing, OAuth Token Refresh): <a href="./architecture/sequence-diagrams.html">docs/architecture/sequence-diagrams.md</a>.</p><h2 id="_6-ai-architecture" tabindex="-1">6. AI Architecture <a class="header-anchor" href="#_6-ai-architecture" aria-label="Permalink to &quot;6. AI Architecture&quot;">​</a></h2><p>Internal design ai-service (router/service layer, ChromaDB schema, LLM routing): <a href="./architecture/ai-service-architecture.html">docs/architecture/ai-service-architecture.md</a>.</p><h2 id="_7-architecture-decision-records-adr" tabindex="-1">7. Architecture Decision Records (ADR) <a class="header-anchor" href="#_7-architecture-decision-records-adr" aria-label="Permalink to &quot;7. Architecture Decision Records (ADR)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ADR</th><th>Quyết định</th></tr></thead><tbody><tr><td><a href="./adr/ADR-001-polyrepo.html">ADR-001</a></td><td>Polyrepo — 7 repo riêng biệt</td></tr><tr><td><a href="./adr/ADR-002-database-split.html">ADR-002</a></td><td>MongoDB + PostgreSQL split</td></tr><tr><td><a href="./adr/ADR-003-rabbitmq.html">ADR-003</a></td><td>RabbitMQ cho async publishing</td></tr><tr><td><a href="./adr/ADR-004-spring-cloud-gateway.html">ADR-004</a></td><td>Spring Cloud Gateway làm API Gateway</td></tr></tbody></table><h2 id="_8-security-model" tabindex="-1">8. Security Model <a class="header-anchor" href="#_8-security-model" aria-label="Permalink to &quot;8. Security Model&quot;">​</a></h2><ul><li>JWT RS256, verify chữ ký tại gateway, re-verify + RBAC tại business-service (business-service là nguồn sự thật duy nhất cho role hiện tại, không tin claim JWT cũ).</li><li>RBAC 2 tầng: Agency-level (chỉ <code>owner_id</code>, check riêng <code>@RequireAgencyOwner</code>) tách biệt Workspace-level (<code>MemberRole</code>, <code>@RequireRole</code>) — xem <a href="./ba/10-roles-permissions-matrix.html">docs/ba/10-roles-permissions-matrix.md</a> §1.1.</li><li>OAuth token (Social Platform) mã hóa AES-256 trước khi gửi qua RabbitMQ tới publisher-service.</li><li>Chi tiết flow: <a href="./architecture/sequence-diagrams.html">docs/architecture/sequence-diagrams.md</a> §4 (OAuth Token Refresh).</li></ul><h2 id="_9-deployment-architecture" tabindex="-1">9. Deployment Architecture <a class="header-anchor" href="#_9-deployment-architecture" aria-label="Permalink to &quot;9. Deployment Architecture&quot;">​</a></h2><ul><li>Docker Compose, 3 file tách rời: <code>docker-compose.infra.yml</code> (postgres/redis/rabbitmq/chromadb), <code>docker-compose.dev.yml</code> (overlay port cho dev), <code>docker-compose.apps.yml</code> (5 service app, build từ sibling repo).</li><li>MongoDB dùng Atlas cloud, không self-host local.</li><li>Chi tiết local run setup: <a href="./architecture/architecture.html">docs/architecture/architecture.html</a> mục &quot;Local Run Setup&quot;.</li></ul><h2 id="_10-use-case-reference" tabindex="-1">10. Use Case Reference <a class="header-anchor" href="#_10-use-case-reference" aria-label="Permalink to &quot;10. Use Case Reference&quot;">​</a></h2><p>105 Use Case đầy đủ, chia 8 domain: <a href="./ba/use-cases/00-index.html">docs/ba/use-cases/00-index.md</a>.</p><h2 id="_11-record-of-changes" tabindex="-1">11. Record of Changes <a class="header-anchor" href="#_11-record-of-changes" aria-label="Permalink to &quot;11. Record of Changes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ngày</th><th>Thay đổi</th></tr></thead><tbody><tr><td>2026-09-17</td><td>v1.0 — biên soạn đầy đủ theo model V2 (Agency→Workspace→Package→Campaign→Task), thay thế toàn bộ giả định V1 cũ trong <code>docs/plan/brandhub-master-plan.md</code> Epic E05</td></tr></tbody></table>',26)])])}const b=a(c,[["render",o]]);export{m as __pageData,b as default};
